import OrderConstant from '../constant/OrderConstant';

export default {
    /**
     * action search order
     * @returns {{type: string}}
     */
    searchOrder: (queryService, searchKey = '', searchAllTime = false) => {
        return {
            type: OrderConstant.SEARCH_ORDER,
            queryService: queryService,
            search_key: searchKey,
            searchAllTime: searchAllTime
        }
    },

    /**
     * action search order result
     * @param orders
     * @param search_criteria
     * @param total_count
     * @param search_key
     * @param searchAllTime
     * @param request_mode
     * @return {{type: string, orders: Array, search_criteria: {}, total_count: number, search_key: string, searchAllTime: boolean, request_mode: *}}
     */
    searchOrderResult: (
        orders = [],
        search_criteria = {},
        total_count = 0,
        search_key = '',
        searchAllTime = false,
        request_mode
    ) => {
        return {
            type: OrderConstant.SEARCH_ORDER_RESULT,
            orders: orders,
            search_criteria: search_criteria,
            total_count: total_count,
            search_key: search_key,
            searchAllTime: searchAllTime,
            request_mode: request_mode
        }
    },

    /**
     * action search order error
     * @param error
     * @returns {{type: string, error: *}}
     */
    searchOrderError: (error) => {
        return {
            type: OrderConstant.SEARCH_ORDER_ERROR,
            error: error
        }
    },

    /**
     * Sync action update order data finish
     * @param items
     * @return {{type: string, orders: Array}}
     */
    syncActionUpdateDataFinish(items = []) {
        return {
            type: OrderConstant.SYNC_ACTION_UPDATE_DATA_FINISH,
            orders: items
        }
    },

    /**
     * Reset updated_orders in order list reducer
     *
     * @returns {{type: string}}
     */
    resetUpdatedOrdersList() {
        return {
            type: OrderConstant.RESET_UPDATED_ORDERS_LIST
        }
    },

    /**
     * Sync deleted order finish
     * @param ids
     * @return {{type: string, ids: Array}}
     */
    syncDeletedOrderFinish(ids = []) {
        return {
            type: OrderConstant.SYNC_DELETED_ORDER_FINISH,
            ids: ids
        }
    },

    /**
     * get list order statuses
     * @param atLoadingPage
     * @returns {{type: string, atLoadingPage: boolean}}
     */
    getListOrderStatuses: (atLoadingPage = false) => {
        return {
            type: OrderConstant.GET_LIST_ORDER_STATUSES,
            atLoadingPage: atLoadingPage
        }
    },

    /**
     * action reprint order
     * @param order
     * @param customer
     * @returns {{type: string, order: *, customer: *}}
     */
    reprintOrder: (order, customer) => {
        return {
            type: OrderConstant.REPRINT_ORDER,
            order,
            customer
        }
    },

    /**
     * Action save order pickup package
     *
     * @param order
     * @param packageId
     * @returns {{type: string, order, customer: *}}
     */
    deliveredOrderPickupPackage: (order, packageId) => {
        return {
            type: OrderConstant.DELIVERED_ORDER_PICKUP_PACKAGE,
            order,
            packageId
        }
    },

    /**
     * Action save order pickup package
     *
     * @param order
     * @returns {{type: string, order, customer: *}}
     */
    saveOrderPickupPackage: (order) => {
        return {
            type: OrderConstant.SAVE_ORDER_PICKUP_ORDER,
            order
        }
    },

    /**
     * action show loading when action click and collect for order start
     * @returns {{type: string}}
     */
    showLoading: () => {
        return {
            type: OrderConstant.SHOW_LOADING
        }
    },

    /**
     * action hide loading when action click and collect for order end
     * @returns {{type: string, showLoading: *}}
     */
    hideLoading: () => {
        return {
            type: OrderConstant.HIDE_LOADING
        }
    },

    /**
     * send email
     * @param order
     * @return {{type: string, order: *, email: string}}
     */
    sendEmail(order, email) {
        return {
            type: OrderConstant.SEND_EMAIL,
            order: order,
            email: email
        }
    },

    /**
     * send email result
     * @param response
     * @returns {{response, type: string}}
     */
    sendEmailResult(response) {
        return {
            type: OrderConstant.SEND_EMAIL_RESULT,
            response: response
        }
    },

    /**
     * add comment
     * @param order
     * @return {{type: string, order: *, email: string}}
     */
    addComment(order, comment, notify, visibleOnFront) {
        return {
            type: OrderConstant.ADD_COMMENT,
            order: order,
            comment: comment,
            notify: notify,
            visibleOnFront: visibleOnFront
        }
    },

    /**
     * add comment result
     * @param order
     * @param
     * @return {{type: string}}
     */
    addCommentResult(response) {
        return {
            type: OrderConstant.ADD_COMMENT_RESULT,
            response: response
        }
    },


    /**
     * Cancel package for order
     *
     * @param order
     * @param packageId
     * @returns {{packageId: *, type: string}}
     */
    cancelPackage: (order, packageId) => {
        return {
            type: OrderConstant.CANCEL_CLICK_AND_COLLECT_PACKAGE,
            order: order,
            packageId: packageId
        }
    },

    /**
     * Save Order Ready Pick Date
     *
     * @param order
     * @param readyPickDate
     * @returns {{orderId, type: string, readyPickDate}}
     */
    saveOrderReadyPickDate: (order, readyPickDate) => {
        return {
            type: OrderConstant.SAVE_ORDER_READY_PICK_DATE,
            order: order,
            readyPickDate: readyPickDate
        }
    }
}



