import React from "react";
import ComponentFactory from '../../../../../framework/factory/ComponentFactory';
import CoreContainer from '../../../../../framework/container/CoreContainer';
import ContainerFactory from "../../../../../framework/factory/ContainerFactory";
import CoreComponent from "../../../../../framework/component/CoreComponent";
import {DateTime} from 'react-datetime-bootstrap';
import moment from "moment";
import "../../../../style/css/DateTime.css";
import OrderAction from "../../../../action/OrderAction";
import StatusConstant from "../../../../constant/order/StatusConstant";
import PermissionConstant from "../../../../constant/PermissionConstant";

export class ReadyPickDate extends CoreComponent {
    static className = 'ReadyPickDate';

    /**
     * On Change Date
     *
     * @param date
     */
    onChangeDate(date) {
        let readyPickDate = '';
        let order = this.props.order;
        let oldReadyPickDate = order && order.extension_attributes && order.extension_attributes.ready_pick_date ?
            order.extension_attributes.ready_pick_date
            : '';
        if (date) {
            readyPickDate = moment(date).format('YYYY-MM-DD');
        }
        if (readyPickDate !== oldReadyPickDate) {
            this.props.actions.showLoading();
            this.props.actions.saveOrderReadyPickDate(order, readyPickDate);
        }
    }

    /**
     * Get Picker Options
     *
     * @returns {{minDate: moment.Moment, format: string}}
     */
    getPickerOptions() {
        return {
            format: "LL",
            minDate: new Date().setHours(0,0,0,0),
            useCurrent: false,
            widgetPositioning: {
                horizontal: 'right'
            },
            ignoreReadonly: true
        }
    }

    /**
     * Check if ready pick date field is disabled
     *
     * @param order
     * @returns {*|boolean}
     */
    isDisabled(order) {
        return (
            !this.isAllowed(PermissionConstant.PERMISSION_SET_READY_PICK_DATE)
            || !order
            || !order.extension_attributes
            || order.extension_attributes.pickup_status === StatusConstant.PICKUP_STATUS_READY_TO_PICK
            || order.extension_attributes.pickup_status === StatusConstant.PICKUP_STATUS_DELIVERED
        );
    }

    /**
     * @inheritDoc
     */
    template() {
        let {order} = this.props;
        let readyPickDate = order && order.extension_attributes && order.extension_attributes.ready_pick_date ?
            order.extension_attributes.ready_pick_date
            : '';
        if (this.props.showLoading) {
            return null;
        }
        return (
            <div className="order-real-date">
                <div className="date">
                    <b>{this.props.t("Ready pickup date")}: </b>
                    <DateTime id={'datepicker-ready-pick-date'}
                              pickerOptions={this.getPickerOptions()}
                              onChange={(date) => this.onChangeDate(date)}
                              value={readyPickDate}
                              disabled={this.isDisabled(order)}
                              readOnly={true}/>
                </div>
            </div>
        );
    }
}

class ReadyPickDateContainer extends CoreContainer {
    static className = 'ReadyPickDateContainer';

    /**
     * map state to component's props
     *
     * @param state
     * @returns {{showLoading: *}}
     */
    static mapState(state) {
        let {
            showLoading
        } = state.core.order.orderList;
        return {
            showLoading
        };
    }

    /**
     * Map Dispatch
     *
     * @param dispatch
     * @returns {{actions: {saveOrderReadyPickDate: (function(*=, *=): *), showLoading: (function(): *)}}}
     */
    static mapDispatch(dispatch) {
        return {
            actions: {
                saveOrderReadyPickDate: (order, readyPickDate) =>
                    dispatch(OrderAction.saveOrderReadyPickDate(order, readyPickDate)),
                showLoading: () =>
                    dispatch(OrderAction.showLoading())
            }
        }
    }
}

/**
 * @type {ReadyPickDate}
 */
export default ContainerFactory.get(ReadyPickDateContainer).withRouter(
    ComponentFactory.get(ReadyPickDate)
);


