import AbstractResourceModel from "../AbstractResourceModel";

export default class LogResourceModel extends AbstractResourceModel {
    static className = 'LogResourceModel';

    /**
     * Constructor
     * @param props
     */
    constructor(props) {
        super(props);
        this.state = {resourceName : 'Log'};
    }

    /**
     * Submit Log
     * @param {string[]} logs
     * @returns {Promise<FetchResult<*>>}
     */
    submitLog(logs = []) {
        return this.getResourceOnline().submitLog(logs);
    }

    /**
     * Call get all log
     *
     * @returns {Object|*|FormDataEntryValue[]|string[]}
     */
    getAll() {
        return this.getResourceOffline().getAll();
    }
}


