import EpicFactory from "../../../framework/factory/EpicFactory";
import LogConstant from "../../constant/log/LogConstant";
import LogAction from "../../action/LogAction";
import LogService from "../../../service/log/LogService";

function SubmitLogEpic(action$) {
    return action$.ofType(LogConstant.SUBMIT_LOG)
        .mergeMap(async () => {
            let result = await LogService.submitAllLogs();
            return LogAction.submitLogResult(result);
        });
}

SubmitLogEpic.className = 'SubmitLogEpic';

export default EpicFactory.get(SubmitLogEpic);



