import {Observable} from 'rxjs';
import OrderConstant from "../../constant/OrderConstant";
import OrderService from "../../../service/sales/OrderService";
import EpicFactory from "../../../framework/factory/EpicFactory";
import {toast} from "react-toastify";
import i18n from "../../../config/i18n";
import _ from "lodash";
import OrderAction from "../../action/OrderAction";
import StatusConstant from "../../constant/order/StatusConstant";

function DeliveredOrderPickupPackageEpic(action$) {
    return action$.ofType(OrderConstant.DELIVERED_ORDER_PICKUP_PACKAGE)
        .mergeMap(action => Observable.from(OrderService.deliveredOrderPickupPackage(action.order, action.packageId))
            .mergeMap((response) => {
                let order = action.order;
                toast.success(
                    i18n.translator.translate('The order package has been successfully delivered.'),
                    {
                        position: toast.POSITION.TOP_CENTER,
                        className: 'wrapper-messages messages-success'
                    }
                );
                const orderCopy = _.clone(order);
                let packageItem = response.data.deliverOrderPickupPackage.package;
                let packages = orderCopy.extension_attributes.packages;
                let index = packages.findIndex(item => item.package_id === packageItem.package_id);
                if (index > -1) {
                    packages[index] = packageItem;
                }

                orderCopy.extension_attributes.pickup_status = StatusConstant.PICKUP_STATUS_DELIVERED;
                orderCopy.state = StatusConstant.STATE_PROCESSING;
                orderCopy.status = StatusConstant.STATE_PROCESSING;
                orderCopy.extension_attributes.packages = packages;

                return [
                    OrderAction.syncActionUpdateDataFinish([orderCopy]),
                    OrderAction.hideLoading()
                ];
            }).catch((error) => {
                toast.error(
                    i18n.translator.translate('Delivery has failed.'),
                    {
                        position: toast.POSITION.TOP_CENTER,
                        className: 'wrapper-messages messages-warning'
                    }
                );
                return [
                    OrderAction.hideLoading()
                ];
            })
        );
}

DeliveredOrderPickupPackageEpic.className = 'DeliveredOrderPickupPackageEpic';

export default EpicFactory.get(DeliveredOrderPickupPackageEpic);


