import {Observable} from 'rxjs';
import ActionLogAction from "../../action/ActionLogAction";
import OrderAction from "../../action/OrderAction";
import OrderConstant from "../../constant/OrderConstant";
import OrderService from "../../../service/sales/OrderService";
import EpicFactory from "../../../framework/factory/EpicFactory";
import {toast} from "react-toastify";
import i18n from "../../../config/i18n";
import _ from 'lodash';
import StatusConstant from "../../constant/order/StatusConstant";

function SaveOrderPickupPackageEpic(action$) {
    return action$.ofType(OrderConstant.SAVE_ORDER_PICKUP_ORDER)
        .mergeMap(action => {
            let order = action.order;
            return Observable.fromPromise(
                OrderService.saveOrderPickupPackage(null, order.entity_id, StatusConstant.PICKUP_STATUS_READY_TO_PICK, order.extension_attributes.location_pickup_id)
            ).mergeMap((response) => {
                if (response.data) {
                    toast.success(
                        i18n.translator.translate(
                            'The order has been successfully packed'
                        ), {
                            position: toast.POSITION.TOP_CENTER,
                            className: 'wrapper-messages messages-success'
                        }
                    );
                    const orderCopy = _.clone(order);
                    let packages = response.data.saveOrderPickupPackage.package;
                    orderCopy.extension_attributes.pickup_status = StatusConstant.PICKUP_STATUS_READY_TO_PICK;
                    if (orderCopy.extension_attributes.packages && Array.isArray(orderCopy.extension_attributes.packages)) {
                        orderCopy.extension_attributes.packages.push(packages);
                    } else {
                        orderCopy.extension_attributes.packages = [packages];
                    }

                    return [
                        OrderAction.syncActionUpdateDataFinish([orderCopy]),
                        OrderAction.hideLoading()
                    ];
                } else if (response.error) {
                    toast.error(
                        i18n.translator.translate(
                            'The packaged order has failed'
                        ), {
                            position: toast.POSITION.TOP_CENTER,
                            className: 'wrapper-messages messages-warning',
                        }
                    );
                    return Observable.of(OrderAction.hideLoading());
                }
            }).catch(() => {
                return [
                    ActionLogAction.syncActionLog(),
                    OrderAction.hideLoading(),
                ];
            })
        });
}

SaveOrderPickupPackageEpic.className = 'SaveOrderPickupPackageEpic';

export default EpicFactory.get(SaveOrderPickupPackageEpic);



