import {Observable} from 'rxjs';
import OrderConstant from "../../constant/OrderConstant";
import OrderService from "../../../service/sales/OrderService";
import EpicFactory from "../../../framework/factory/EpicFactory";
import {toast} from "react-toastify";
import i18n from "../../../config/i18n";
import _ from "lodash";
import OrderAction from "../../action/OrderAction";
import StatusConstant from "../../constant/order/StatusConstant";

function CancelPackageOfOrderEpic(action$) {
    return action$.ofType(OrderConstant.CANCEL_CLICK_AND_COLLECT_PACKAGE)
        .mergeMap(action => Observable.from(OrderService.cancelPackage(action.order, action.packageId))
            .mergeMap((response) => {
                let order = action.order;
                toast.success(
                    i18n.translator.translate(
                        'The order package has been successfully canceled.'
                    ),{
                        position: toast.POSITION.TOP_CENTER,
                        className: 'wrapper-messages messages-success'
                    }
                );
                const orderCopy = _.clone(order);
                let packageItem = response.data.cancelOrderPickupPackage.package;
                orderCopy.extension_attributes.pickup_status = StatusConstant.PICKUP_STATUS_PENDING;
                let packages = orderCopy.extension_attributes.packages;

                let index = packages.findIndex(item => item.package_id === packageItem.package_id);
                if (index > -1) {
                    packages[index] = packageItem;
                }

                orderCopy.extension_attributes.packages = packages;

                return [
                    OrderAction.syncActionUpdateDataFinish([orderCopy]),
                    OrderAction.hideLoading()
                ];
            }).catch(() => {
                return [
                    OrderAction.hideLoading()
                ];
            })
        );
}

CancelPackageOfOrderEpic.className = 'CancelPackageOfOrderEpic';

export default EpicFactory.get(CancelPackageOfOrderEpic);



