/**
 * Init GLOBAL_VARIABLES to store config
 */
if (typeof window.clickandcollect === 'undefined') {
    window.clickandcollect = {config: {}};
}
const GLOBAL_VARIABLES = window.clickandcollect.config;

/**
 * get allow permission of current staff
 *
 * @return {Array}
 *
 * */
export function getPermission() {
    if ( !GLOBAL_VARIABLES.config) return [];
    if ( !GLOBAL_VARIABLES.config.permissions) {
        return [];
    }
    let permissions = GLOBAL_VARIABLES.config.permissions;
    if ( permissions.length) {
        return permissions;
    }
    return [];
}

export default GLOBAL_VARIABLES;



