import GraphqlAbstract from "./GraphqlAbstract";
import DataResourceFactory from "../../../framework/factory/DataResourceFactory";

export class GraphqlOrder extends GraphqlAbstract {
    static className = 'GraphqlOrder';

    /**
     *
     * @param packageId
     * @param orderId
     * @param status
     * @param locationId
     * @return promise
     */
    saveOrderPickupPackage(packageId, orderId, status, locationId) {
        return this.mutate(`
            mutation OrderPickupPackage(
                $input: PickupPackageInput!
            ){
              saveOrderPickupPackage(
                input: $input
              ) {
                package {
                  package_id
                  order_id
                  location_id
                  status
                }
              }
            }`,
            {
                input: {
                    package_id: packageId,
                    order_id: orderId,
                    location_id: locationId,
                    status: status
                }
            }
        );
    }

    /**
     * Cancel package of order
     *
     * @param locationId
     * @param packageId
     * @returns {Promise<FetchResult<*>>}
     */
    cancelPackage(locationId, packageId) {
        return this.mutate(
            `
            mutation CancelOrderPickupPackage(
                $input: PickupPackageActionInput!
            ){
              cancelOrderPickupPackage(
                input: $input
              ) {
                package {
                  package_id
                  order_id
                  location_id
                  status
                }
              }
            }`,
            {
                input: {
                    package_id: packageId,
                    location_id: locationId
                }
            }
        )
    }

    /**
     * Save Order Ready Pick Date
     *
     * @param orderId
     * @param readyPickDate
     * @returns {Promise<FetchResult<*>>}
     */
    saveOrderReadyPickDate(orderId, readyPickDate) {
        return this.mutate(`
            mutation SaveOrderReadyPickDate(
                $input: ReadyPickDateInput!
            ){
              saveOrderReadyPickDate(
                input: $input
              ) {
                result
              }
            }`,
            {
                input: {
                    order_id: orderId,
                    ready_pick_date: readyPickDate
                }
            }
        );
    }

    /**
     * Delivered Order Pickup Package Graph Ql
     * @param locationId
     * @param packageId
     * @return promise
     */
    deliveredOrderPickupPackage(locationId, packageId) {
        return this.mutate(`
            mutation DeliverOrderPickupPackage(
                $input: PickupPackageActionInput!
            ){
              deliverOrderPickupPackage(
                input: $input
              ) {
                package {
                  package_id
                  order_id
                  location_id
                  status
                }
              }
            }`,
            {
                input: {
                    package_id: packageId,
                    location_id: locationId
                }
            }
        );
    }
}

/**
 * @type {GraphqlOrder}
 */
export default DataResourceFactory.get(GraphqlOrder);



