import React, {Fragment} from "react";
import * as _ from "lodash";
import CoreComponent from '../../../framework/component/CoreComponent';
import ComponentFactory from '../../../framework/factory/ComponentFactory';
import CoreContainer from '../../../framework/container/CoreContainer';
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import SmoothScrollbar from "smooth-scrollbar";
import DateTimeHelper from "../../../helper/DateTimeHelper";
import OrderService from "../../../service/sales/OrderService";
import OrderItem from "./order-detail/detail-content/OrderItem";
import {Panel} from "react-bootstrap";
import moment from "moment/moment";
import ContentPaymentItem from "./order-detail/detail-content/ContentPaymentItem";
import ShippingMethod from "./order-detail/detail-content/ShippingMethod";
import ShippingAddress from './order-detail/detail-content/ShippingAddress';
import BillingAddress from './order-detail/detail-content/BillingAddress';
import OrderAction from "../../action/OrderAction";
import StatusConstant from "../../constant/order/StatusConstant";
import CommentItem from "./order-detail/detail-content/CommentItem";
import PermissionConstant from "../../constant/PermissionConstant";
import OrderHelper from "../../../helper/OrderHelper";
import TaxHelper from "../../../helper/TaxHelper";
import OrderWeeeDataService from "../../../service/weee/OrderWeeeDataService";
import PaymentConstant from "../../constant/PaymentConstant";
import Permission from "../../../helper/Permission";
import LocationService from "../../../service/LocationService";
import NumberHelper from "../../../helper/NumberHelper";
import layout from "../../../framework/Layout";
import backIcon from "../../style/images/back.svg";
import MenuAction from "../../action/MenuAction";
import ReadyPickDate from "./order-detail/detail-content/ReadyPickDate";

export class OrderDetail extends CoreComponent {
    static className = 'OrderDetail';

    setBlockContentElement = element => {
        this.block_content = element;
        if (!this.scrollbarOrderDetail) {
            this.scrollbarOrderDetail = SmoothScrollbar.init(this.block_content);
        }
    };

    /**
     *
     * @param props
     */
    constructor(props) {
        super(props);
        this.state = {
            printBtnClassName: 'btn btn-default'
        }
        props.actions.hideMenuToggle();
    }

    /**
     * Component will receive props
     * @param nextProps
     */
    componentWillReceiveProps(nextProps) {
        if (this.props.order !== nextProps.order) {
            if (nextProps.order && !nextProps.order.items) {
                return;
            }
            if (this.scrollbarOrderDetail) {
                this.scrollbarOrderDetail.scrollTo(0, 0);
            }
        }
    }

    /**
     * component will unmount
     */
    componentWillUnmount() {
        if (this.scrollbarOrderDetail) {
            SmoothScrollbar.destroy(this.scrollbarOrderDetail);
        }
    }

    /**
     * handle click add note
     */
    handleClickAddComment() {
        this.props.openAddComment();
    }

    /**
     * handle cancel package
     */
    handleCancelPackage(order) {
        if (order.extension_attributes && order.extension_attributes.location_pickup_id) {
            let packages = order.extension_attributes.packages;
            if (packages.length) {
                let packageItemReadyToPick = packages.find(
                    packageItem => packageItem.status === StatusConstant.PICKUP_STATUS_READY_TO_PICK
                );
                if (packageItemReadyToPick && packageItemReadyToPick.package_id) {
                    this.props.actions.showLoading();
                    this.props.actions.cancelPackage(order, packageItemReadyToPick.package_id);
                }
            }
        }
    }

    /**
     * Can cancel package or not
     * @param order
     */
    isCanCancelPackage(order) {
        let cancelPackage = false;
        if (order.extension_attributes && order.extension_attributes.pickup_status) {
            let pickUpStatus = order.extension_attributes.pickup_status;
            if (pickUpStatus === StatusConstant.PICKUP_STATUS_READY_TO_PICK) {
                cancelPackage = true;
            }
        }
        return cancelPackage;
    }

    /**
     * handle click send email
     */
    handleClickSendEmail() {
        this.props.openSendEmail();
    }

    /**
     * Print order by order data
     * @param order
     */
    handleClickPrint(order) {
        this.props.actions.reprintOrder(order, null);
    }

    /**
     * Handle click packed order
     *
     * @param order
     */
    handleClickPacked(order) {
        if (order &&
            order.extension_attributes &&
            order.extension_attributes.pickup_status === StatusConstant.PICKUP_STATUS_PENDING
        ) {
            this.props.actions.showLoading();
            this.props.actions.saveOrderPickupPackage(order);
        }
    }

    /**
     * Handle click customer collected order
     *
     * @param order
     * @returns {Promise<void>}
     */
    handleClickCustomerCollected(order) {
        if (order &&
            order.extension_attributes &&
            order.extension_attributes.pickup_status === StatusConstant.PICKUP_STATUS_READY_TO_PICK
        ) {
            let packages = order.extension_attributes.packages;
            if (packages.length) {
                let packageItemReadyToPick = packages.find(
                    packageItem => packageItem.status === StatusConstant.PICKUP_STATUS_READY_TO_PICK
                );
                if (packageItemReadyToPick && packageItemReadyToPick.package_id) {
                    this.props.actions.showLoading();
                    this.props.actions.deliveredOrderPickupPackage(order, packageItemReadyToPick.package_id);
                }
            }
        }
    }

    /**
     * get display location
     * @param order
     * @return {*}
     */
    getDisplayLocation(order) {
        if (
            Permission.isAllowed(PermissionConstant.PERMISSION_MANAGE_ORDER_CREATED_AT_ALL_LOCATION)
            || Permission.isAllowed(PermissionConstant.PERMISSION_MANAGE_ALL_ORDERS_IN_SYSTEM)
        ) {
            let locationId = order.pos_location_id ? order.pos_location_id : order.warehouse_id;
            if (locationId) {
                let location = LocationService.getLocationById(locationId);
                if (location) {
                    return this.props.t("Location: {{name}}", {name: location.name})
                }
            }
        }
        return "";
    }

    /**
     * Get discount amount
     * @param order
     * @returns {number}
     */
    getDiscountAmount(order) {
        return order && order.discount_amount ? Math.abs(order.discount_amount) : 0;
    }

    /**
     * Return loading flag value
     *
     * @return boolean
     */
    isLoading() {
        return this.props.isDetailLoading;
    }

    /**
     * Get Display Pickup Status
     *
     * @param order
     * @returns {JSX.Element|null}
     */
    getDisplayPickupStatus(order) {
        if (order && order.extension_attributes && order.extension_attributes.pickup_status) {
            return (
                <span className={
                    "status pickup-status " + order.extension_attributes.pickup_status
                }>
                    {
                        this.props.t(
                            OrderService.getDisplayPickupStatus(order.extension_attributes.pickup_status)
                        )
                    }
                </span>
            );
        }
        return null;
    }

    /**
     * Back To Order List
     */
    backToOrderList() {
        this.props.backToOrderList();
    }

    /**
     * Get Expected Pickup Date Template
     *
     * @param order
     * @returns {JSX.Element}
     */
    getExpectedPickupDateTemplate(order) {
        let expectedPickupTime = OrderService.getExpectedPickupTime(order);
        if (expectedPickupTime.pickupTime) {
            let date = expectedPickupTime.isDateOnly ?
                moment(expectedPickupTime.pickupTime).format('LL')
                : moment(expectedPickupTime.pickupTime).format('LLL');
            return (
                <div className="order-expected-date">
                    <div className="date">
                        <b>{this.props.t("Expected pickup time")}</b>: {date}
                    </div>
                </div>
            );
        }
        return null;
    }

    /**
     * Get order detail info template
     *
     * @param order
     * @returns {JSX.Element}
     */
    getOrderDetailInfoTemplate(order) {
        let created_at = order ?
            moment(DateTimeHelper.convertDatabaseDateTimeToLocalDate(order.created_at)).format('L LT') : "";
        let customer_name = (order && order.customer_firstname && order.customer_lastname && !order.customer_is_guest) ?
            (order.customer_firstname + ' ' + order.customer_lastname) :
            this.props.t('Guest');
        let billingAddress = OrderService.getBillingAddress(order);
        let telephone = order && !order.customer_is_guest && billingAddress ?
            (billingAddress.telephone || this.props.t('N/A')) :
            null;
        let paymentStatus = OrderService.getPaymentStatus(order);
        return (
            <div className="row">
                <div>
                    <div className="order-detail">
                        <div>
                            {
                                this.props.t(
                                    "Order Date: {{created_at}}",
                                    {created_at: created_at}
                                )
                            }
                        </div>
                        <div>{this.getDisplayLocation(order)}</div>
                        <div>
                            {
                                this.props.t(
                                    "Customer: {{name}}",
                                    {name: customer_name}
                                )
                            }
                        </div>
                        {
                            telephone ?
                                <div>
                                    {
                                        this.props.t(
                                            "Customer Phone: {{telephone}}",
                                            {telephone: telephone}
                                        )
                                    }
                                </div> :
                                telephone
                        }
                        <div className="old">
                            {
                                order.pos_staff_name ?
                                    this.props.t("Staff: {{name}}", {name: order.pos_staff_name})
                                    :
                                    ''
                            }
                        </div>
                        {layout('order')('orderHistory')('staff_name_layout')('order_detail_staff_name_after')()(this)}
                        <div className="order-status">
                            {this.getDisplayPickupStatus(order)}
                            <span className={"status " + paymentStatus.className}>
                                {paymentStatus.value}
                            </span>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    /**
     * Get Order Items Template
     *
     * @param order
     * @returns {JSX.Element}
     */
    getOrderItemsTemplate(order) {
        return (
            <Panel eventKey="1" defaultExpanded key={Math.random()}>
                <Panel.Heading>
                    <Panel.Title toggle>{this.props.t('Items Ordered')}</Panel.Title>
                </Panel.Heading>
                <Panel.Body collapsible>
                    {
                        order.items.map(item => {
                            return <OrderItem key={'' + item.item_id + Math.random()}
                                              item={item} order={order}/>
                        })
                    }
                </Panel.Body>
            </Panel>
        );
    }

    /**
     * Get Payment Method Template
     *
     * @param order
     * @returns {JSX.Element}
     */
    getPaymentMethodTemplate(order) {
        let paymentStatus = OrderService.getPaymentStatus(order);
        let other_payment;
        if (order && order.payments) {
            let actutal_total_paid = 0;
            order.payments.forEach((payment) => {
                if (payment.type !== PaymentConstant.TYPE_REFUND) {
                    actutal_total_paid = NumberHelper.addNumber(payment.amount_paid, actutal_total_paid);
                }
            });
            if (actutal_total_paid < order.total_paid) {
                let amount = order.total_paid - actutal_total_paid;
                other_payment = {
                    amount_paid: amount,
                    base_amount_paid: amount,
                    card_type: null,
                    is_paid: 1,
                    method: "otherpayment",
                    payment_date: null,
                    receipt: null,
                    reference_number: null,
                    title: "Other",
                    type: 0
                };
            }
        }
        return (
            <Panel eventKey="2" key={Math.random()}>
                <Panel.Heading>
                    <Panel.Title toggle>{this.props.t('Payment Method')}</Panel.Title>
                </Panel.Heading>
                <Panel.Body collapsible>
                    <div className="text-right">
                        <span className={"status " + paymentStatus.className}>
                            {paymentStatus.value}
                        </span>
                    </div>
                    <ul className="payment-method">
                        {
                            order.payments ?
                                order.payments.map((payment, index) =>
                                    payment.type !== PaymentConstant.TYPE_REFUND ?
                                        <ContentPaymentItem key={index} payment={payment}
                                                            order={order}/> :
                                        null
                                )
                                :
                                null
                        }
                        {
                            other_payment ?
                                <ContentPaymentItem payment={other_payment} order={order}/> : null
                        }
                    </ul>
                </Panel.Body>
            </Panel>
        );
    }

    /**
     * Get Shipping Method Template
     * @param order
     * @returns {JSX.Element}
     */
    getShippingMethodTemplate(order) {
        if (!order.is_virtual) {
            return (
                <Panel eventKey="3" key={Math.random()}>
                    <Panel.Heading>
                        <Panel.Title toggle>
                            {this.props.t('Shipping Method')}
                        </Panel.Title>
                    </Panel.Heading>
                    <Panel.Body collapsible>
                        <ShippingMethod order={order}/>
                    </Panel.Body>
                </Panel>
            );
        }
        return null;
    }

    /**
     * Get Shipping Address Template
     *
     * @param order
     * @returns {JSX.Element|null}
     */
    getShippingAddressTemplate(order) {
        if (!order.is_virtual) {
            return (
                <Panel eventKey="4" key={Math.random()}>
                    <Panel.Heading>
                        <Panel.Title toggle>
                            {this.props.t('Shipping Address')}
                        </Panel.Title>
                    </Panel.Heading>
                    <Panel.Body collapsible>
                        <ShippingAddress order={order}/>
                    </Panel.Body>
                </Panel>
            );
        }
        return null;
    }

    /**
     * Get Billing Address Template
     *
     * @param order
     * @returns {JSX.Element}
     */
    getBillingAddressTemplate(order) {
        return (
            <Panel eventKey="5" key={Math.random()}>
                <Panel.Heading>
                    <Panel.Title toggle>{this.props.t('Billing Address')}</Panel.Title>
                </Panel.Heading>
                <Panel.Body collapsible>
                    <BillingAddress order={order}/>
                </Panel.Body>
            </Panel>
        );
    }

    /**
     * Get order total template
     *
     * @param order
     * @returns {JSX.Element}
     */
    getOrderTotalTemplate(order) {
        let giftcardDiscount = order && order.gift_voucher_gift_codes ? order.gift_voucher_discount : 0;
        let discount = this.getDiscountAmount(order) - giftcardDiscount;

        let weeeTotal = order && order.items ? OrderWeeeDataService.getTotalAmounts(order.items, order) : "";
        return (
            <div className="order-info">
                <div className="row">
                    <div>
                        <div className="order-total">
                            <ul>
                                <li>
                                    <span className="title">{this.props.t('Subtotal')}</span>
                                    <span className="value">
                                        {OrderService.getDisplaySubtotal(order)}
                                    </span>
                                </li>
                                <li>
                                    <span className="title">
                                        {OrderHelper.getDiscountDisplay(order)}
                                    </span>
                                    <span className="value">-{OrderHelper.formatPrice(discount, order)}</span>
                                </li>

                                {layout('order')('order_detail_layout')('total_discount_after')()(this)}

                                {
                                    !order.is_virtual ?
                                        <li>
                                            <span className="title">
                                                {this.props.t('Shipping')}
                                            </span>
                                            <span className="value">
                                                {OrderService.getDisplayShippingAmount(order)}
                                            </span>
                                        </li>
                                        : null
                                }
                                {
                                    giftcardDiscount ?
                                        <li>
                                            <span className="title">{this.props.t('Gift Card')}</span>
                                            <span className="value">
                                                {OrderHelper.formatPrice(-giftcardDiscount, order)}
                                            </span>
                                        </li> : ''
                                }
                                <li>
                                    <span className="title">{this.props.t('FPT')}</span>
                                    <span className="value">
                                        {OrderHelper.formatPrice(weeeTotal, order)}
                                    </span>
                                </li>
                                {
                                    !TaxHelper.orderDisplayZeroTaxSubTotal() && order.tax_amount === 0
                                        ?
                                        null
                                        :
                                        <li>
                                            <span className="title">{this.props.t('Tax')}</span>
                                            <span className="value">
                                                {OrderHelper.formatPrice(order.tax_amount, order)}
                                            </span>
                                        </li>
                                }

                                {layout('order')('order_detail_layout')('total_tax_after')()(this)}

                                <li>
                                    <span className="title">{this.props.t('Grand Total')}</span>
                                    <span className="value">
                                        {OrderHelper.formatPrice(order.grand_total, order)}
                                    </span>
                                </li>

                                {layout('order')('order_detail_layout')('grand_total_after')()(this)}

                                <li>
                                    <span className="title">{this.props.t('Total Paid')}</span>
                                    <span className="value">
                                        {OrderHelper.formatPrice(order.total_paid, order)}
                                    </span>
                                </li>
                                {
                                    order.pos_change ?
                                        <li>
                                            <span className="title">
                                                {this.props.t('Total Change')}
                                            </span>
                                            <span className="value">
                                                {OrderHelper.formatPrice(order.pos_change, order)}
                                            </span>
                                        </li>
                                        :
                                        null
                                }
                                {
                                    (order.total_refunded !== undefined)  ?
                                        <li>
                                            <span className="title">
                                                {this.props.t('Total Refunded')}
                                            </span>
                                            <span className="value">
                                                {OrderHelper.formatPrice(order.total_refunded, order)}
                                            </span>
                                        </li>
                                        :
                                        null
                                }
                            </ul>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    /**
     * Get Comment History Template
     *
     * @param order
     * @returns {JSX.Element|null}
     */
    getCommentHistoryTemplate(order) {
        let statusHistory = (order && order.status_histories) ? order.status_histories : [];
        statusHistory = _.orderBy(statusHistory, 'created_at', 'desc');
        if (statusHistory && statusHistory.length) {
            return (
                <Panel eventKey="6" key={Math.random()}>
                    <Panel.Heading>
                        <Panel.Title toggle>{this.props.t('Comment History')}</Panel.Title>
                    </Panel.Heading>
                    <Panel.Body collapsible>
                        <ul className="comment-history">
                            {
                                statusHistory.map((comment, index) =>
                                    <CommentItem key={comment.entity_id + '_' + index}
                                                 comment={comment}/>
                                )
                            }
                        </ul>
                    </Panel.Body>
                </Panel>
            );
        }
        return null;
    }

    /**
     * Get Actions Template
     *
     * @param order
     * @returns {JSX.Element|null}
     */
    getActionsTemplate(order) {
        if (order) {
            return (
                <div className="block-actions">
                    <ul className={"actions hidden-refund"}>
                        {layout('order')('order_detail_layout')('actions')('print_before')()(this)}
                        <li>
                            <button
                                className={this.state.printBtnClassName}
                                onClick={() => this.handleClickPrint(order)}>
                                {
                                    this.props.t('Print')
                                }
                            </button>
                        </li>
                        {layout('order')('order_detail_layout')('actions')('email_before')()(this)}
                        <li>
                            <button className="btn btn-default email-button"
                                    onClick={() => this.handleClickSendEmail()}>
                                {this.props.t('Email')}</button>
                        </li>
                        {layout('order')('order_detail_layout')('actions')('add_note_before')()(this)}
                        <li>
                            <button className="btn btn-default add-note-button"
                                    onClick={() => this.handleClickAddComment()}>
                                {this.props.t('Add Note')}
                            </button>
                        </li>
                        {layout('order')('order_detail_layout')('actions')('pack_before')()(this)}
                        <li className={(!this.isAllowed(PermissionConstant.PERMISSION_CREATE_PACKAGE) ? 'hidden' : '')}>
                            <button className={"btn btn-default packed-button " + (order.extension_attributes && order.extension_attributes.pickup_status !== StatusConstant.PICKUP_STATUS_PENDING  ? 'disabled' : '')}
                                    onClick={() => this.handleClickPacked(order)}>
                                {this.props.t('Packed')}
                            </button>
                        </li>
                        {layout('order')('order_detail_layout')('actions')('cancel_package_before')()(this)}
                        <li className={(!this.isAllowed(PermissionConstant.PERMISSION_CANCEL_PACKAGE) ? 'hidden' : '')}>
                            <button className={"btn btn-default "
                            + (!this.isCanCancelPackage(order) ? 'disabled' : '')}
                                    onClick={() => this.handleCancelPackage(order)}>
                                {this.props.t('Cancel Package')}
                            </button>
                        </li>
                        {layout('order')('order_detail_layout')('actions')('cancel_package_before')()(this)}
                        <li className={(!this.isAllowed(PermissionConstant.PERMISSION_DELIVERY_PACKAGE) ? 'hidden' : '')}>
                            <button className={"btn btn-default textbox-wrap "
                            + (!this.isCanCancelPackage(order) ? 'disabled' : '')}
                                    onClick={() => this.handleClickCustomerCollected(order)}>
                                {this.props.t('Customer Collected')}
                            </button>
                        </li>
                    </ul>
                </div>
            );
        }
        return null;
    }

    /**
     * template
     * @returns {*}
     */
    template() {
        let {order, isLoading} = this.props;
        if (order && !order.items) {
            order = null;
        }
        return (<Fragment>
            <div className="back-icon" onClick={() => this.backToOrderList()}>
                <span><img src={backIcon} alt={'Back'}/></span>
            </div>
            <div className="wrapper-order-right click-collect-order">
                <div id="packageLoader" className={this.props.showLoading ? "logout_modal" : "hidden"}>
                    <div className="loading-logout"
                         style={{display: 'block'}}/>
                </div>
                <div className="block-title">{order ? order.increment_id : ''}</div>

                <div className="loader-product"
                     style={{
                         display: (this.isLoading() ? 'block' : 'none'),
                         marginTop: '300px',
                         marginBottom: '500px'
                     }}>
                </div>

                <div ref={this.setBlockContentElement} className="block-content">

                    {
                        !order ?
                            (
                                isLoading || this.isLoading() ?
                                    <div/>
                                    :
                                    <div className="page-notfound">
                                        <div className="icon"/>
                                        {
                                            this.props.showNoInternet ?
                                                this.props.t('Please connect to Internet to find orders')
                                                :
                                                this.props.t('No order is found.')
                                        }
                                    </div>
                            )
                            :
                            <div>
                                <div className="order-info">
                                    <div className="date-pick">
                                        {this.getExpectedPickupDateTemplate(order)}
                                        <ReadyPickDate order={order}/>
                                    </div>
                                    {this.getOrderDetailInfoTemplate(order)}
                                </div>
                                <div id="accordion" className="panel-group" role="tablist" aria-multiselectable="true">
                                    {this.getOrderItemsTemplate(order)}
                                    <div className="panel-flex">
                                        {this.getPaymentMethodTemplate(order)}
                                        {this.getShippingMethodTemplate(order)}
                                        {this.getShippingAddressTemplate(order)}
                                        {this.getBillingAddressTemplate(order)}
                                    </div>
                                    {this.getOrderTotalTemplate(order)}
                                    {this.getCommentHistoryTemplate(order)}
                                </div>
                            </div>
                    }
                </div>
                {this.getActionsTemplate(order)}
            </div>
        </Fragment>);
    }
}

class OrderDetailContainer extends CoreContainer {
    static className = 'OrderDetailContainer';

    /**
     * map state to component's props
     *
     * @param state
     * @returns {{showLoading: *}}
     */
    static mapState(state) {
        let {
            showLoading
        } = state.core.order.orderList;
        return {
            showLoading
        };
    }

    static mapDispatch(dispatch) {
        return {
            actions: {
                reprintOrder: (order, customer) =>
                    dispatch(OrderAction.reprintOrder(order, customer)),
                saveOrderPickupPackage: (order) =>
                    dispatch(OrderAction.saveOrderPickupPackage(order)),
                deliveredOrderPickupPackage: (order, packageId) =>
                    dispatch(OrderAction.deliveredOrderPickupPackage(order, packageId)),
                showLoading: () =>
                    dispatch(OrderAction.showLoading()),
                updateOrder: orderData => dispatch(OrderAction.syncActionUpdateDataFinish([orderData])),
                hideMenuToggle: () => dispatch(MenuAction.hideMenuToggle()),
                cancelPackage: (orderData, packageId) => dispatch(OrderAction.cancelPackage(orderData, packageId))
            }
        }
    }
}

export default ContainerFactory.get(OrderDetailContainer).withRouter(
    ComponentFactory.get(OrderDetail)
);



