import AbstractResourceModel from "../AbstractResourceModel";

export default class ErrorLogResourceModel extends AbstractResourceModel {
    static className = 'ErrorLogResourceModel';

    /**
     * Constructor
     * @param props
     */
    constructor(props) {
        super(props);
        this.state = {resourceName : 'ErrorLog'};
    }
}


