import React from "react";
import ComponentFactory from '../../../../framework/factory/ComponentFactory';
import CoreContainer from '../../../../framework/container/CoreContainer';
import ContainerFactory from "../../../../framework/factory/ContainerFactory";
import CoreComponent from "../../../../framework/component/CoreComponent";
import OrderService from "../../../../service/sales/OrderService";

export class FilterPickupStatus extends CoreComponent {
    static className = 'FilterPickupStatus';

    /**
     * on change checkbox value
     * @param event
     * @param value
     */
    onChangeCheckbox(event, value) {
        let {selectedPickupStatus} = this.props;
        if (event.target.checked) {
            selectedPickupStatus.push(value);
        } else {
            let index = selectedPickupStatus.indexOf(value);
            selectedPickupStatus.splice(index, 1);
        }

        this.props.changeSelectedPickupStatus(selectedPickupStatus);
    }

    /**
     * @inheritDoc
     */
    template() {
        let {selectedPickupStatus} = this.props;
        return (
            <div className="filter-pickup-status search-alltime select-option">
                {
                    Object.entries(OrderService.getPickupStatusAndLabelMapping()).map(([status, label]) => {
                        let isSelected = selectedPickupStatus.includes(status);
                        return (
                            <label className={"filter-order" + (isSelected ? " selected" : "")} key={status}>
                                <span className="wrap-filter">
                                    <input type="checkbox"
                                           checked={isSelected}
                                           onChange={(event) => this.onChangeCheckbox(event, status)}/>
                                    <span>{this.props.t(label)}</span>
                                </span>
                            </label>
                        );
                    })
                }
            </div>
        );
    }
}

class FilterPickupStatusContainer extends CoreContainer {
    static className = 'FilterPickupStatusContainer';
}

/**
 * @type {FilterPickupStatus}
 */
export default ContainerFactory.get(FilterPickupStatusContainer).withRouter(
    ComponentFactory.get(FilterPickupStatus)
);


