import CoreService from "../CoreService";
import ServiceFactory from "../../framework/factory/ServiceFactory";
import LogResourceModel from "../../resource-model/log/LogResourceModel";
import LogConstant from "../../view/constant/log/LogConstant";
import Config from "../../config/Config";

export class LogService extends CoreService {
    static className = 'LogService';
    resourceModel = LogResourceModel;

    /**
     * Save log
     * @param {object} log
     */
    saveLog(log) {
        if (!log || !Object.keys(log).length) {
            return;
        }
        log = this.prepareLogData(log);
        return this.saveToDb([log]);
    }

    /**
     * Prepare Log Data
     * @param {object} log
     * @returns {*}
     */
    prepareLogData(log) {
        if (!log[LogConstant.LOG_TIME]) {
            log[LogConstant.LOG_TIME] = (new Date()).toISOString();
        }
        if (!log[LogConstant.SOURCE]) {
            log[LogConstant.SOURCE] = this.getSource();
        }
        if (!log[LogConstant.APP]) {
            log[LogConstant.APP] = LogConstant.APP_NAME;
        }
        return log;
    }

    /**
     * Get log source (site's domain)
     * @returns {string|*}
     */
    getSource() {
        if (process.env.NODE_ENV !== 'production') {
            return process.env.REACT_APP_POS_URL;
        }
        return window.location.href.split(Config.basename)[0];
    }

    /**
     * Submit Log
     * @param {string[]} logs
     * @returns {Promise<FetchResult<*>>}
     */
    submitLog(logs = []) {
        return this.getResourceModel().submitLog(logs);
    }

    /**
     * Submit all logs
     * @returns {Promise<boolean>}
     */
    async submitAllLogs() {
        if (!window.navigator.onLine) {
            return false;
        }
        try {
            let allLogs = await this.getAll();
            let i, chunk = 200;
            for (i = 0; i < allLogs.length; i += chunk) {
                let logs = allLogs.slice(i, i + chunk);
                let submitData = [], ids =[];
                submitData = logs.map(log => {
                    ids.push(log[LogConstant.ID]);
                    return JSON.stringify(log);
                });
                let response = await this.submitLog(submitData);
                if (response
                    && response.data
                    && response.data.submitLog
                    && response.data.submitLog.status
                ) {
                    // Delete submitted logs
                    await this.deleteItems(ids);
                } else {
                    return false
                }
            }
            return true;
        } catch (e) {
            return false;
        }
    }

    /**
     * Get all log
     *
     * @returns {Object|*|FormDataEntryValue[]|string[]}
     */
    getAll() {
        return this.getResourceModel().getAll();
    }
}

/** @type LogService */
let logService = ServiceFactory.get(LogService);

export default logService;



