import {combineEpics} from 'redux-observable';
import ScheduleSubmitLogEpic from "./log/ScheduleSubmitLogEpic";
import SubmitLogEpic from "./log/SubmitLogEpic";

/**
 * Combine all epic log
 * @type {Epic<Action, any, any, T> | any}
 */
const logEpic = combineEpics(
    ScheduleSubmitLogEpic,
    SubmitLogEpic
);

export default logEpic;



