import LogConstant from "../constant/log/LogConstant";

export default {
    /**
     * Submit log
     * @returns {{type: string}}
     */
    submitLog: () => {
        return {
            type: LogConstant.SUBMIT_LOG
        }
    },

    /**
     * Submit log result
     * @param result
     * @returns {{result, type: string}}
     */
    submitLogResult: (result) => {
        return {
            type: LogConstant.SUBMIT_LOG_RESULT,
            result: result
        }
    },

    /**
     * Schedule Submit Log
     * @returns {{type: string}}
     */
    scheduleSubmitLog: () => {
        return {
            type: LogConstant.SCHEDULE_SUBMIT_LOG
        }
    }
}


