import React from 'react';
import {CoreComponent} from "../../../framework/component";
import {toast} from "react-toastify";
import GLOBAL_VARIABLES from "../../../config/Config";
import UserService from "../../../service/user/UserService";
import LocationService from "../../../service/LocationService";
import 'react-select/dist/react-select.css';
import '../../style/css/Location.css';
import SyncService from "../../../service/sync/SyncService";
import CoreContainer from "../../../framework/container/CoreContainer";
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import ComponentFactory from "../../../framework/factory/ComponentFactory";
import LogoutPopupAction from "../../action/LogoutPopupAction";
import Select from 'react-select';
import LocalStorageHelper from "../../../helper/LocalStorageHelper";

class SelectLocation extends CoreComponent {
    static className = 'SelectLocation';

    /**
     * constructor
     * @param props
     */
    constructor(props) {
        super(props);

        this.state = {
            selectedLocation: null,
        };

        this.handleChangeLocation = this.handleChangeLocation.bind(this);
        this.handleEnterLocation = this.handleEnterLocation.bind(this);
        this.handleLogout = this.handleLogout.bind(this);
        this.checkOnceLocation = this.checkOnceLocation.bind(this);
        this.handleAssignLocation = this.handleAssignLocation.bind(this);
    }

    /**
     * component will mount
     */
    componentWillMount() {
        let session = GLOBAL_VARIABLES.session;
        let staffId = GLOBAL_VARIABLES.staff_id;
        if (!session) {
            session = UserService.getSession();
            GLOBAL_VARIABLES.session = session;
        }
        if (!staffId) {
            staffId = UserService.getStaffId();
            GLOBAL_VARIABLES.staff_id = staffId;
        }
        if (!session || !staffId) {
            UserService.removeSession();
            UserService.removeStaff();
            window.location.reload();
        }

        let redirectToLoading = false;
        if (this.checkOnceLocation() && !this.props.error) {
            redirectToLoading = true;
            let {locations} = this.props;
            let location = locations[0];
            this.handleAssignLocation(staffId, location);
        }
        if (redirectToLoading || this.checkLocationSavedLocalStorage()) {
            GLOBAL_VARIABLES.location_id = LocationService.getCurrentLocationId();
            GLOBAL_VARIABLES.location_name = LocationService.getCurrentLocationName();
            GLOBAL_VARIABLES.location_address = LocationService.getCurrentLocationAddress();
            GLOBAL_VARIABLES.location_telephone = LocationService.getCurrentLocationTelephone();
            return this.props.history.push('/loading');
        }
    }

    /**
     * component will receive props
     * @param nextProps
     */
    componentWillReceiveProps(nextProps) {
        if (nextProps.error && nextProps.error !== "") {
            toast.error(
                this.props.t(nextProps.message),
                {
                    className: 'wrapper-messages messages-warning'
                }
            );
            UserService.clearLocationInLocalStorage();
        }
    }

    /**
     *  if request logout is done ,reload page
     *  if request logout has error ,show error alert
     *
     */
    componentDidUpdate() {
        if ( Object.keys(this.props.success).length) {
            this.props.reInit();
            return this.props.history.push({
                pathname: '/login'
            });

        }
    }

    /**
     * check location
     * @returns {boolean}
     */
    checkLocationSavedLocalStorage() {
        const locationId = LocationService.getCurrentLocationId();
        const locationName = LocationService.getCurrentLocationName();

        return (locationId && locationName);
    }

    /**
     * check if has once location
     * @returns {boolean}
     */
    checkOnceLocation() {
        let {locations} = this.props;
        return (locations && locations.length === 1);
    }

    /**
     * change value location selected
     * @param location
     */
    handleChangeLocation = (location) => {
        if (location) {
            this.setState({
                selectedLocation: location,
            });
        } else {
            this.setState({
                selectedLocation: null,
            });
        }
    };

    /**
     * handle event click to enter location button
     */
    handleEnterLocation() {
        let staffId = GLOBAL_VARIABLES.staff_id;
        if (!staffId) {
            staffId = UserService.getStaffId();
            GLOBAL_VARIABLES.staff_id = staffId;
        }
        if (staffId) {
            let {selectedLocation} = this.state;
            this.handleAssignLocation(staffId, selectedLocation);
        }
    }

    /**
     * assign location for user and save to localStorage
     * @param staffId
     * @param location
     */
    handleAssignLocation(staffId, location) {
        let locationId = location.location_id;
        SyncService.saveNeedSync(this.checkNeedSync(location));
        LocationService.saveCurrentLocation(
            locationId, location.name, location.address, location.telephone
        );
        LocationService.saveReceiptInformation(location.receipt_header, location.receipt_footer);
        LocationService.setCurrentStoreName(location.store_name);

        LocalStorageHelper.set(LocalStorageHelper.STORE_CODE, location.store_code);
        if (location.website_id !== undefined) {
            UserService.saveWebsiteId(JSON.stringify(location.website_id));
        }
        GLOBAL_VARIABLES.location_id = LocationService.getCurrentLocationId();
        GLOBAL_VARIABLES.location_name = LocationService.getCurrentLocationName();
        GLOBAL_VARIABLES.location_address = LocationService.getCurrentLocationAddress();
        GLOBAL_VARIABLES.location_telephone = LocationService.getCurrentLocationTelephone();
        this.props.history.push('/loading');
    }

    /**
     * compare location to check need sync some table in indexeddb
     * @param location
     * @returns {string}
     */
    checkNeedSync(location) {
        let locationIdLocaStorage = LocationService.getCurrentLocationId();
        if (location.location_id) {
            if (
                Number(location.location_id) === Number(locationIdLocaStorage) &&
                LocalStorageHelper.get(LocalStorageHelper.STORE_CODE) === location.store_code
            ) {
                return '0';
            }
        }
        return '1';
    }

    /**
     * sort array by alphabet
     * @param array
     * @param fieldSort
     * @return {*}
     */
    sortByAlphabet(array, fieldSort) {
        if (array && array.length > 0) {
            let result = [...array];
            if (fieldSort) {
                result = result.sort(function (a, b) {
                    if (typeof a.status !== 'undefined') {
                        if (a.status < b.status) return -1;
                        if (a.status > b.status) return 1;

                    }
                    if (a[fieldSort] < b[fieldSort]) return -1;
                    if (a[fieldSort] > b[fieldSort]) return 1;
                    return 0;
                });
            }
            return result;
        }
        return [];
    }

    /**
     * handle event click logout
     * note: not remove staff_id in local storage
     */
    handleLogout() {
        this.props.logout();
    }

    /**
     * Get display locations
     *
     * @param locations
     * @returns {*}
     */
    getDisplayLocations(locations) {
        /* sort location by alphabet */
        let displayLocations = this.sortByAlphabet(locations, "name");

        displayLocations.map(item => {
            item.value = item.location_id;
            item.label = item.name;
            return item;
        });
        return displayLocations;
    }

    /**
     * template render
     * @returns {*}
     */
    template() {
        let {locations, loading} = this.props;
        locations = this.getDisplayLocations(locations);
        return (
            <div id="selection_location_pos" className="selection_location_pos">
                <div className="wrapper-login">
                    <div className="form-login">
                        <strong className="logo">
                            <a href=""><img src={this.props.logoUrl} alt=""/></a>
                        </strong>
                        <div className="form-group">
                            <Select
                                placeholder={this.props.t("Choose a Location")}
                                value={this.state.selectedLocation}
                                onChange={this.handleChangeLocation}
                                options={locations}
                                clearable={false}
                                searchable={false}
                                noResultsText={''}/>
                        </div>
                        <div className="form-group text-center">
                            <button type="button"
                                    className={'btn btn-default' + (!loading ? '' : ' disabled')}
                                    disabled={loading}
                                    onClick={this.handleEnterLocation}>
                                {this.props.t('Enter To Location')}
                            </button>
                            <div className="btn-link-logout"
                                 onClick={this.handleLogout}>
                                <span>{this.props.t('Logout')}</span>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        );
    }
}

class SelectLocationContainer extends CoreContainer {
    static className = 'SelectLocationContainer';

    /**
     * map state to props
     * @param state
     * @returns {{error, handleAssignLocation, locations: Array, loading, logoUrl: *}}
     */
    static mapState(state) {
        const {error, loading} = state.core && state.core.user;
        const {success} = state.core.logout;
        let locations = [];
        let locationsString = LocationService.getLocationsInLocalStorage();
        if (locationsString && locationsString !== "") {
            locations = JSON.parse(locationsString);
            locations = locations.filter(location => location.pos);
        }
        let logoUrl = UserService.getLocalLogo();
        return {
            error,
            locations,
            loading,
            logoUrl,
            success
        }
    }

    /**
     * map dispatch to props
     * @param dispatch
     * @returns {{userAssignPos: function(*=, *=, *=): *}}
     */
    static mapDispatch(dispatch) {
        return {
            logout: () => dispatch(LogoutPopupAction.clickLogOut()),
            reInit: () => dispatch(LogoutPopupAction.reInit())
        };
    }
}

export default ContainerFactory.get(SelectLocationContainer).getConnect(
    ComponentFactory.get(SelectLocation));



