import * as PrintConstant from "../constant/PrintConstant";
import OrderConstant from "../constant/OrderConstant";


/**
 *  initial State for reducer
 *
 * @type {{isOpen: boolean}}
 */
const initState = {
    showLoading: false
};

/**
 * receive action from Checkout Action
 *
 * @param state
 * @param action
 * @returns {*}
 */
export default function PrintReducer(state = initState, action) {
    switch (action.type) {
        case PrintConstant.FINISH_PRINT:
            return {
                ...state,
                orderData: null,
                isReprint: false,
                quote: null,
                reportData: null,
                customer: null,
                creditmemo: null,
                showLoading: false
            };
        case OrderConstant.REPRINT_ORDER:
            return {
                ...state,
                orderData: action.order,
                isReprint: true,
                customer: action.customer,
                showLoading: true
            };
        default: return state
    }
}



