import {Observable} from 'rxjs';
import ActionLogAction from "../../action/ActionLogAction";
import OrderAction from "../../action/OrderAction";
import OrderConstant from "../../constant/OrderConstant";
import OrderService from "../../../service/sales/OrderService";
import EpicFactory from "../../../framework/factory/EpicFactory";
import {toast} from "react-toastify";
import i18n from "../../../config/i18n";
import _ from 'lodash';

function SaveOrderReadyPickDateEpic(action$) {
    return action$.ofType(OrderConstant.SAVE_ORDER_READY_PICK_DATE)
        .mergeMap(action => {
            let order = action.order;
            return Observable.fromPromise(
                OrderService.saveOrderReadyPickDate(order.entity_id, action.readyPickDate)
            ).mergeMap((response) => {
                if (response.data
                    && response.data.saveOrderReadyPickDate
                    && response.data.saveOrderReadyPickDate.result
                ) {
                    toast.success(
                        i18n.translator.translate(
                            'Updated ready pick date successfully'
                        ), {
                            position: toast.POSITION.TOP_CENTER,
                            className: 'wrapper-messages messages-success'
                        }
                    );
                    const orderCopy = _.clone(order);
                    orderCopy.extension_attributes.ready_pick_date = action.readyPickDate;
                    return [
                        OrderAction.syncActionUpdateDataFinish([orderCopy]),
                        OrderAction.hideLoading()
                    ];
                } else if (response.error) {
                    toast.error(
                        i18n.translator.translate(
                            'Unable to update ready pick date'
                        ), {
                            position: toast.POSITION.TOP_CENTER,
                            className: 'wrapper-messages messages-warning',
                        }
                    );
                    return Observable.of(OrderAction.hideLoading());
                }
            }).catch(() => {
                toast.error(
                    i18n.translator.translate(
                        'Unable to update ready pick date'
                    ), {
                        position: toast.POSITION.TOP_CENTER,
                        className: 'wrapper-messages messages-warning',
                    }
                );
                return [
                    ActionLogAction.syncActionLog(),
                    OrderAction.hideLoading(),
                ];
            })
        });
}

SaveOrderReadyPickDateEpic.className = 'SaveOrderReadyPickDateEpic';

export default EpicFactory.get(SaveOrderReadyPickDateEpic);



