import OmcAbstract from "./OmcAbstract";
import ApiResourceConstant from "../../view/constant/data-resource/ApiResourceConstant";
import RestUser from "./rest/RestUser";

export default class OmcUser extends OmcAbstract {
    static className = 'OmcUser';

    apiResources = {
        [ApiResourceConstant.REST]: RestUser,
    };

    /**
     * Login with username and password
     *
     * @param username
     * @param password
     * @returns {Promise}
     */
    login(username, password) {
        return this.getApiResource().login(username, password);
    }

    /**
     * Continue Login
     *
     * @returns {*}
     */
    continueLogin(){
        return this.getApiResource().continueLogin();
    }

    /**
     * get logo form server
     */
    getLogo() {
        return this.getApiResource().getLogo();
    }

    /**
     * logout with session
     * @return {Promise}
     */
    logout() {
        return this.getApiResource().logout();
    }
}




