import GraphqlAbstract from "./GraphqlAbstract";
import DataResourceFactory from "../../../framework/factory/DataResourceFactory";

export class GraphqlLog extends GraphqlAbstract {
    static className = 'GraphqlLog';

    /**
     * Submit Log
     * @param {string[]} logs
     * @returns {Promise<FetchResult<*>>}
     */
    submitLog(logs = []) {
        return this.mutate(`
            mutation SubmitLog(
                $input: [String!]!
            ){
              submitLog(
                input: $input
              ) {
                status
              }
            }`,
            {
                input: logs
            }
        );
    }
}

/**
 * @type {GraphqlLog}
 */
export default DataResourceFactory.get(GraphqlLog);



