import OmcAbstract from "./OmcAbstract";
import ApiResourceConstant from "../../view/constant/data-resource/ApiResourceConstant";
import GraphqlLog from "./graphql/GraphqlLog";

export default class OmcLog extends OmcAbstract {
    static className = 'OmcLog';

    apiResources = {
        [ApiResourceConstant.GRAPHQL]: GraphqlLog
    };
    defaultResource = ApiResourceConstant.GRAPHQL;

    /**
     * Submit Log
     * @param {string[]} logs
     * @returns {Promise<FetchResult<*>>}
     */
    submitLog(logs = []) {
        return this.getGraphqlResource().submitLog(logs);
    }
}


