import MenuConstant from "../constant/MenuConstant";

/**
 *  action emit whenever user click MenuItem
 *
 * @param {Object} active
 * @return {{type, active: *}}
 */
export const clickMenuItem = (active) => {
    return {
        type: MenuConstant.CLICK_MENU_ITEM,
        active
    }
};

/**
 * action emit whenever user click Logout button
 *
 * @return {{type}}
 */
export const clickLogoutItem = () => {
    return {
        type: MenuConstant.CLICK_LOGOUT_ITEM,
    }
};

/**
 * toggle menu
 *
 * @return {{type}}
 */
export const toggle= () => {
    return {
        type: MenuConstant.TOGGLE,
    }
};

/**
 * Show menu toggle
 *
 * @return {{type}}
 */
export const showMenuToggle= () => {
    return {
        type: MenuConstant.SHOW_MENU_TOGGLE,
    }
};

/**
 * Show menu toggle
 *
 * @return {{type}}
 */
export const hideMenuToggle= () => {
    return {
        type: MenuConstant.HIDE_MENU_TOGGLE,
    }
};

/**
 * combine actions to export
 * @type {{clickMenuItem: function(Object), clickLogoutItem: function()}}
 */
const MenuAction = {
    clickMenuItem,
    toggle,
    clickLogoutItem,
    showMenuToggle,
    hideMenuToggle
};

export default MenuAction


