import React from "react";
import ComponentFactory from '../../../../framework/factory/ComponentFactory';
import CoreContainer from '../../../../framework/container/CoreContainer';
import ContainerFactory from "../../../../framework/factory/ContainerFactory";
import CoreComponent from "../../../../framework/component/CoreComponent";
import OrderService from "../../../../service/sales/OrderService";
import OrderHelper from "../../../../helper/OrderHelper";
import moment from "moment";

export class Order extends CoreComponent {
    static className = 'Order';

    /**
     * get price label
     * @returns {{className: string, value: string}}
     */
    getPriceLabel() {
        return OrderService.getPriceLabel(this.props.order);
    }

    /**
     * handle select order
     * @param order
     */
    selectOrder(order) {
        this.props.selectOrder(order);
    }

    /**
     * Get customer name
     * @param order
     * @returns {string}
     */
    getCustomerName(order) {
        if (order.customer_firstname && order.customer_lastname) {
            return order.customer_firstname + ' ' + order.customer_lastname;
        } else if (order.extension_attributes
            && order.extension_attributes.customer_firstname
            && order.extension_attributes.customer_lastname) {
            return order.extension_attributes.customer_firstname + ' ' + order.extension_attributes.customer_lastname;
        }
        return '';
    }

    /**
     * Get Expected Pickup Date Template
     *
     * @param order
     * @returns {JSX.Element|null}
     */
    getExpectedPickupDateTemplate(order) {
        let expectedPickupTime = OrderService.getExpectedPickupTime(order);
        if (expectedPickupTime.pickupTime) {
            let date = expectedPickupTime.isDateOnly ?
                moment(expectedPickupTime.pickupTime).format('ll')
                : moment(expectedPickupTime.pickupTime).format('lll');
            return (
                <span className="value"><b>{this.props.t("Pickup time")}</b>: {date}</span>
            );
        }
        return null;
    }

    /**
     * template
     * @returns {*}
     */
    template() {
        let {order, isActive} = this.props;
        let priceLabel = this.getPriceLabel();
        let customerName = this.getCustomerName(order);
        let pickupStatus = order.extension_attributes.pickup_status;
        return (
            <li className={"item " + (isActive ? 'active' : '')}
                onClick={() => this.selectOrder(order)}>
                <div className="item-info">
                    <div className="name">
                        <span className="value">{order.increment_id}</span>
                        {
                            customerName ?
                                <span className="value">{customerName}</span>
                                : null
                        }
                        {this.getExpectedPickupDateTemplate(order)}
                        <span className={"status " + pickupStatus}>
                            {
                                this.props.t(OrderService.getDisplayPickupStatus(pickupStatus))
                            }
                        </span>
                    </div>
                    <div className="price">
                        <span className="value">{OrderHelper.formatPrice(order.grand_total, order)}</span>
                        <span className={"price-label " + priceLabel.className}>{priceLabel.value}</span>
                    </div>
                </div>
            </li>
        );
    }
}

class OrderContainer extends CoreContainer {
    static className = 'OrderContainer';
}

/**
 * @type {Order}
 */
export default ContainerFactory.get(OrderContainer).withRouter(
    ComponentFactory.get(Order)
);


