import AbstractResourceModel from "../AbstractResourceModel";

export default class LocationResourceModel extends AbstractResourceModel {
    static className = 'LocationResourceModel';

    /**
     * constructor
     *
     * @param props
     */
    constructor(props) {
        super(props);
        this.state = {resourceName : 'Location'};
    }
}




