import {Observable} from 'rxjs';
import EpicFactory from "../../../framework/factory/EpicFactory";
import LogConstant from "../../constant/log/LogConstant";
import LogAction from "../../action/LogAction";

/**
 * Schedule submit log epic
 * @param action$
 */
function ScheduleSubmitLogEpic(action$) {
    let isRunning = false;
    return action$.ofType(LogConstant.SCHEDULE_SUBMIT_LOG)
        .mergeMap(() => {
            if (isRunning) {
                return Observable.empty();
            } else {
                isRunning = true;
                return Observable.concat(
                    Observable.of(LogAction.submitLog()),
                    Observable.interval(5 * 60 * 1000).map(() => LogAction.submitLog())
                );
            }
        });
}

ScheduleSubmitLogEpic.className = 'ScheduleSubmitLogEpic';

export default EpicFactory.get(ScheduleSubmitLogEpic);



