import OmcAbstract from "./OmcAbstract";
import ApiResourceConstant from "../../view/constant/data-resource/ApiResourceConstant";
import RestOrder from "./rest/RestOrder";
import GraphqlOrder from "./graphql/GraphqlOrder";

export default class OmcOrder extends OmcAbstract {
    static className = 'OmcOrder';

    apiResources = {
        [ApiResourceConstant.REST]: RestOrder,
        [ApiResourceConstant.GRAPHQL]: GraphqlOrder
    };

    /**
     * get list order statuses
     * @return {Promise<any>}
     */
    getListOrderStatuses() {
        return this.getApiResource().getListOrderStatuses();
    }

    /**
     * get path api send email
     * @return {string}
     */
    getPathSendEmailOrder() {
        return this.getApiResource().getPathSendEmailOrder();
    }

    /**
     * get path api add comment
     * @return {string}
     */
    getPathAddComentOrder() {
        return this.getApiResource().getPathAddComentOrder();
    }

    /**
     * get path api load order
     * @return {string}
     */
    getPathLoadOrder() {
        return this.getApiResource().getPathLoadOrder();
    }

    /**
     * reload order
     * @param orderIncrement
     * @return {Promise<any>}
     */
    loadOrderByIncrement(orderIncrement) {
        return this.getApiResource().loadOrderByIncrement(orderIncrement);
    }

    /**
     * Save package order
     *
     * @param packageId
     * @param orderId
     * @param status
     * @param locationId
     * @return {Promise<any>}
     */
    saveOrderPickupPackage(packageId, orderId, status, locationId) {
        return this.getGraphqlResource().saveOrderPickupPackage(packageId, orderId, status, locationId);
    }

    /**
     * Cancel package order
     *
     * @param locationId
     * @param packageId
     * @returns {Promise<FetchResult<*>>|Promise<*>|{packageId: *, type: string}}
     */
    cancelPackage(locationId, packageId) {
        return this.getGraphqlResource().cancelPackage(locationId, packageId);
    }

    /**
     * Save Order Ready Pick Date
     *
     * @param orderId
     * @param readyPickDate
     * @returns {Promise<FetchResult<*>>}
     */
    saveOrderReadyPickDate(orderId, readyPickDate) {
        return this.getGraphqlResource().saveOrderReadyPickDate(orderId, readyPickDate);
    }

    /**
     * Save package order
     *
     * @param locationId
     * @param packageId
     * @return {Promise<any>}
     */
    deliveredOrderPickupPackage(locationId, packageId) {
        return this.getGraphqlResource().deliveredOrderPickupPackage(locationId, packageId);
    }
}



