import React from "react";
import ComponentFactory from '../../../../../framework/factory/ComponentFactory';
import CoreContainer from '../../../../../framework/container/CoreContainer';
import ContainerFactory from "../../../../../framework/factory/ContainerFactory";
import CoreComponent from "../../../../../framework/component/CoreComponent";
import OrderService from "../../../../../service/sales/OrderService";
import Config from "../../../../../config/Config";
import DateTimeHelper from "../../../../../helper/DateTimeHelper";
import moment from "moment/moment";
import ShippingConstant from "../../../../constant/ShippingConstant";
import StatusConstant from "../../../../constant/order/StatusConstant";

export class ShippingMethod extends CoreComponent {
    static className = 'ShippingMethod';

    /**
     * get display delivery date
     * @return {string}
     */
    getDisplayDeliveryDate() {
        let {order} = this.props;
        let deliveryDate = '';
        if (Config.config.shipping.delivery_date) {
            let date = 'N/A';

            if (order.shipping_method && order.pos_delivery_date) {
                date = moment(
                    DateTimeHelper.convertDatabaseDateTimeToLocalDate(order.pos_delivery_date)
                ).format('L LT');
            }

            deliveryDate = (
                <li>
                    <div className="title">{this.props.t('Delivery Date')}</div>
                    <div className="value">{date}</div>
                </li>
            );
        }
        return deliveryDate;
    }

    /**
     * Get display pickup time info
     *
     * @returns {JSX.Element|null}
     */
    getDisplayPickupTime() {
        let {order} = this.props;
        if (!order || order.shipping_method !== ShippingConstant.CLICK_AND_COLLECT_SHIPPING_METHOD_CODE) {
            return null;
        }
        if (order.extension_attributes
            && order.extension_attributes.pickup_status === StatusConstant.PICKUP_STATUS_PENDING
            && order.extension_attributes.is_enough_qty_in_stock === false
        ) {
            return (
                <li>
                    <div className="title">
                        {this.props.t("There are some out of stock items in that order, please check it.")}
                    </div>
                </li>
            );
        }
        let message = this.props.t("Customer does not choose expected pickup time.");
        let expectedPickupTime = OrderService.getExpectedPickupTime(order);
        if (expectedPickupTime.pickupTime) {
            let pickupTime = expectedPickupTime.isDateOnly ?
                moment(expectedPickupTime.pickupTime).format('LL')
                : moment(expectedPickupTime.pickupTime).format('LLL');
            pickupTime = `<b>${pickupTime}</b>`;
            message = this.props.t(
                "Customer want to collect at {{pickupTime}}",
                {
                    pickupTime
                }
            );
        }
        return (
            <li>
                <div className="title" dangerouslySetInnerHTML={{__html: message}}/>
            </li>
        );
    }

    /**
     * template
     * @returns {*}
     */
    template() {
        let {order} = this.props;
        return (
            <ul className="shipping-method">
                <li>
                    <div className="title" dangerouslySetInnerHTML={{__html: order.shipping_description}} />
                    <div className="value">
                        {OrderService.getShippingMethodAmount(order)}
                    </div>
                </li>
                {this.getDisplayDeliveryDate()}
                {this.getDisplayPickupTime()}
            </ul>
        );
    }
}

class ShippingMethodContainer extends CoreContainer {
    static className = 'ShippingMethodContainer';
}

/**
 * @type {ShippingMethod}
 */
export default ContainerFactory.get(ShippingMethodContainer).withRouter(
    ComponentFactory.get(ShippingMethod)
);


