import AbstractResourceModel from "../AbstractResourceModel";
import SyncConstant from "../../view/constant/SyncConstant";

export default class OrderResourceModel extends AbstractResourceModel {
    static className = 'OrderResourceModel';

    /**
     * Constructor
     * @param props
     */
    constructor(props) {
        super(props);
        this.state = {
            resourceName: 'Order',
            dataType: SyncConstant.TYPE_ORDER
        };
    }

    /**
     * get list order statuses
     * @return {Promise<any>}
     */
    getListOrderStatuses() {
        return this.getResourceOnline().getListOrderStatuses();
    }

    /**
     *
     * @param orderIncrement
     * @return {*|Promise<any>}
     */
    loadOrderByIncrement(orderIncrement) {
        let resourceOnline = this.getResourceOnline();
        /**
         *
         * @type {OmcOrder} resourceOnline
         */
        return resourceOnline.loadOrderByIncrement(orderIncrement);
    }

    /**
     *
     * @param packageId
     * @param orderId
     * @param status
     * @param locationId
     * @return: promise
     */
    saveOrderPickupPackage(packageId, orderId, status, locationId) {
        return this.getResourceOnline().saveOrderPickupPackage(packageId, orderId, status, locationId);
    }

    /**
     * Cancel package
     *
     * @param locationId
     * @param packageId
     * @returns {Promise<FetchResult<*>>|{packageId: *, type: string}|Promise<*>}
     */
    cancelPackage(locationId, packageId) {
        return this.getResourceOnline().cancelPackage(locationId, packageId);
    }

    /**
     * Save Order Ready Pick Date
     *
     * @param orderId
     * @param readyPickDate
     * @returns {Promise<FetchResult<*>>}
     */
    saveOrderReadyPickDate(orderId, readyPickDate) {
        return this.getResourceOnline().saveOrderReadyPickDate(orderId, readyPickDate);
    }

    /**
     *
     * @param locationId
     * @param packageId
     * @return: promise
     */
    deliveredOrderPickupPackage(locationId, packageId) {
        return this.getResourceOnline().deliveredOrderPickupPackage(locationId, packageId);
    }
}



