import React from 'react';
import ServiceFactory from "../framework/factory/ServiceFactory";
import StarWebPrintService from "./printer/StarWebPrintService";
import * as RasterizeHTML from 'rasterizehtml';
import StylePrintComponent2x, {
    BARCODE_FONT_SIZE as BARCODE_FONT_SIZE_2X, BARCODE_HEIGHT as BARCODE_HEIGHT_2X, BARCODE_WIDTH as BARCODE_WIDTH_2X
} from "../view/component/print/StylePrintComponent2x";
import StylePrintComponent, {
    BARCODE_FONT_SIZE, BARCODE_HEIGHT, BARCODE_WIDTH
} from "../view/component/print/StylePrintComponent";
import {toast} from "react-toastify";
import i18n from "../config/i18n";
import {isIOS, isMobileSafari, isTablet} from 'react-device-detect';
import {listen} from "../event-bus";

let IS_READY_ON_APPLE = false;
const APP_PAGE_COMPONENT_ID = 'receipt-canvas';

export class PrinterService {
    static className = 'PrinterService';
    constructor() {
        if (!this.isApple()) {
            return;
        }
        listen('user-logout-after', () => {
            IS_READY_ON_APPLE = false;
        });
    }
    /**
     *
     * @param target
     */
    removeWindow = (target) => {
        setTimeout(() => {
            target.parentNode.removeChild(target);
        }, 500);
    };

    /**
     *
     * @returns {{component: *, BARCODE_WIDTH: number, BARCODE_FONT_SIZE: number, BARCODE_HEIGHT: number}}
     */
    getStyleForPrint() {
        if (this.canUseApiPrint()) {
            return {
                BARCODE_FONT_SIZE: BARCODE_FONT_SIZE_2X,
                BARCODE_HEIGHT: BARCODE_HEIGHT_2X,
                BARCODE_WIDTH: BARCODE_WIDTH_2X,
                StylePrintComponent: <StylePrintComponent2x/>
            }
        }

        return {
            BARCODE_FONT_SIZE,
            BARCODE_HEIGHT,
            BARCODE_WIDTH,
            StylePrintComponent: <StylePrintComponent/>
        }
    }

    /**
     *
     * @returns {boolean}
     */
    canUseApiPrint() {
        return StarWebPrintService.isEnable();
    }

    /**
     *
     */
    updateUIBeforeCallApiPrint() {
        toast.success(
            i18n.translator.translate("Printer request has been sent successfully!"),
            {
                position: toast.POSITION.BOTTOM_CENTER,
                className: 'wrapper-messages messages-success'
            }
        );
    }

    /**
     *
     * @param reason
     */
    showError(reason) {
        toast.error(
            i18n.translator.translate(reason),
            {
                className: 'wrapper-messages messages-warning',
                autoClose: 5000
            }
        );
    }

    /**
     *
     * @param printWindow
     * @param callbacks
     * @returns {*}
     */
    async printCanvas(printWindow, callbacks) {
        const {onBeforePrint, onAfterPrint} = callbacks;

        if (onBeforePrint) {
            await onBeforePrint();
        }

        let printReceipt = printWindow.contentDocument.body.firstChild;
        this.updateUIBeforeCallApiPrint();
        const canvas = this.getCanvas();
        this.setCanvasSize(canvas, printReceipt);

        if (!this.isApple() || IS_READY_ON_APPLE) {
            await RasterizeHTML.drawHTML(printReceipt.innerHTML, canvas);
            return this.starWebPrintServicePrint({canvas, onAfterPrint});
        }
        //todo: I don't know why, on first time, order barcode always is missed.
        await RasterizeHTML.drawHTML(printReceipt.innerHTML, canvas);
        await RasterizeHTML.drawHTML(printReceipt.innerHTML, canvas);
        await RasterizeHTML.drawHTML(printReceipt.innerHTML, canvas);
        IS_READY_ON_APPLE = 1;
        return this.starWebPrintServicePrint({canvas, onAfterPrint});
    }

    /**
     *
     * @returns {boolean}
     */
    isApple() {
        return isIOS || isMobileSafari || isTablet
    }
    /**
     *
     * @param canvas
     * @param onAfterPrint
     */
    starWebPrintServicePrint({canvas, onAfterPrint}) {
        StarWebPrintService.print(canvas);
        if (onAfterPrint) {
            onAfterPrint();
        }
    }
    /**
     *
     * @param content
     * @param title
     * @param option
     */
    print(content, title, option) {
        if (StarWebPrintService.isEnable()) {
            // clear prev print window
            if (this.currentPrintWindow) {
                this.removeWindow(this.currentPrintWindow);
                this.currentPrintWindow = null;
            }

            const printWindow = document.createElement('iframe');
            printWindow.style.position = 'absolute';
            printWindow.style.top = '-1000px';
            printWindow.style.left = '-1000px';
            this.currentPrintWindow = printWindow;
            document.body.appendChild(printWindow);
            setTimeout(() => {
                this.printCanvas(printWindow, {});
            }, 10);
            return;
        }

        let print_window = window.open('', title, option);
        if (print_window) {
            print_window.document.open();
            print_window.document.write(content);
            print_window.print();
            print_window.close();
        } else {
            window.alert("Your browser has blocked the automatic popup, " +
                "please change your browser setting or print the receipt manually");
        }
    }
    /**
     * Print window target
     *
     * @param target
     */
    printTarget(target) {
        if (this.isChromeOnIOS()) {
            /* Chrome on IOS has problem on print iframe popup*/
            this.print(
                target.contentWindow.document.documentElement.innerHTML,
                '',
                'width=1,height=1'
            );
        } else {
            target.contentWindow.focus();
            target.contentWindow.print();
        }
    }

    /**
     * Is chrome ios or not
     *
     * @returns {boolean}
     */
    isChromeOnIOS() {
        return /CriOS/i.test(navigator.userAgent);
    }

    /**
     *
     * @return {HTMLElement}
     */
    getCanvas() {
        let canvas = document.getElementById(APP_PAGE_COMPONENT_ID);
        if (!canvas) {
            canvas = document.createElement('canvas');
            canvas.id = APP_PAGE_COMPONENT_ID;
            document.body.appendChild(canvas);
        }
        return canvas;
    }

    /**
     *
     * @param {HTMLElement} canvas
     * @param {ChildNode} printReceipt
     */
    setCanvasSize(canvas, printReceipt) {
        if (!canvas) {
            return;
        }
        const printReceiptBounding = printReceipt.getBoundingClientRect();
        canvas.width = printReceiptBounding.width;
        canvas.height = printReceiptBounding.height;
    }

}

/**
 * @type {PrinterService}
 */
let printerService = ServiceFactory.get(PrinterService);

export default printerService;



